	@Test
	void sameProofAcrossActualContextsCannotTransferBoundaryOrVector() {
		AtomicInteger crossed = new AtomicInteger();
		PackedCostModel model = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				throw new AssertionError("the actual session owns costing");
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query, PackedProviderWork work,
					PackedProviderMemory memory) {
				return new PackedCostSession() {
					private PackedPhysicalRegion.Factory factory;
					private PackedPhysicalRegion region;
					private PackedPhysicalRegion.Coverage outerProof;
					private PackedStrategyRequest first;
					private PackedStrategyRequest.Boundary firstBoundary;
					private PackedStrategyRequest.Vector firstVector;

					@Override
					public void bindPhysicalRegions(PackedPhysicalRegion.Factory value) {
						factory = value;
					}

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						output.setRows(1, 1);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						output.setRows(1, 1);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (relationId != query.rootRelationId()) {
							output.setRows(1, 1);
							return;
						}
						if (first == null && context.prefixRelationCount() == 0) {
							region = ready(factory.open());
							var root = region.root();
							outerProof = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root }));
							first = ready(factory.openStrategyRequest(region, root, context));
							try (var active = ready(first.activate())) {
								var outer = ready(first.recognize(ready(first.bindCoverage(outerProof))));
								var left = ready(first.boundary(outer, 0, PackedStrategyRequest.BoundaryScope.LOCAL,
										quantities(7)));
								firstBoundary = ready(
										first.boundary(outer, 1, PackedStrategyRequest.BoundaryScope.INCLUSIVE,
												quantities(20)));
								firstVector = ready(first.compose(outer, ready(first.quote(outer, quantities(2))),
										new PackedStrategyRequest.Boundary[] { left, firstBoundary }));
							}
						} else if (first != null && context.prefixRelationCount() > 0 && crossed.get() == 0) {
							try (var second = ready(factory.openStrategyRequest(region, region.root(), context));
									var active = ready(second.activate())) {
								var outer = ready(second.recognize(ready(second.bindCoverage(outerProof))));
								var quote = ready(second.quote(outer, quantities(2)));
								var left = ready(second.boundary(outer, 0, PackedStrategyRequest.BoundaryScope.LOCAL,
										quantities(7)));
								assertThrows(IllegalArgumentException.class,
										() -> second.compose(outer, quote, new PackedStrategyRequest.Boundary[] { left,
												firstBoundary }));
								assertThrows(IllegalArgumentException.class,
										() -> second.boundary(outer, 1, firstVector));
								assertThrows(IllegalStateException.class, first::prefixRelationCount);
								crossed.incrementAndGet();
							}
						}
						output.setRows(1, 1);
					}

					@Override
					public void close() {
						if (first != null) {
							first.close();
						}
						if (region != null) {
							region.close();
						}
					}
				};
			}
		};
		PackedCascadesPlanner.optimize(new Join(pattern("a"), new Join(pattern("b"), pattern("c"))),
				OptimizationGoal.root(), new PackedPlannerLimits(1_000_000L, Long.MAX_VALUE, 64L * 1024 * 1024), model);
		assertEquals(1, crossed.get(), "both distinct actual contexts must be reached");
	}

	@Test
	void actualMemoryRefusalIsStickyForTheRequest() {
		runProvider((factory, work, memory, context) -> {
			try (var region = ready(factory.open())) {
				var root = region.root();
				var raw = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root }));
				try (var request = ready(factory.openStrategyRequest(region, root, context));
						var active = ready(request.activate())) {
					var candidate = ready(request.recognize(ready(request.bindCoverage(raw))));
					assertFalse(memory.tryReserve(Long.MAX_VALUE));
					assertFalse(memory.tryReserve(0), "a stopped request must not accept later raw memory admissions");
					assertEquals(PackedPhysicalRegion.Status.RESOURCE_REFUSED,
							request.quote(candidate, quantities(1)).status());
				}
			}
		});
	}

