	private static void captureDescriptor(TupleExpr source, AtomicReference<PackedStrategyRequest.Descriptor> target) {
		runProvider(source, (factory, work, memory, context) -> {
			try (var region = ready(factory.open())) {
				var root = region.root();
				var proof = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root }));
				try (var request = ready(factory.openStrategyRequest(region, root, context));
						var active = ready(request.activate())) {
					var candidate = ready(request.recognize(ready(request.bindCoverage(proof))));
					target.set(ready(request.detach(candidate, "rdf4j.test", "fused", 1)));
				}
			}
		});
	}

	@Test
	void detachedCoverageIdentityIsIndependentOfOfferOrder() {
		runProvider((factory, work, memory, context) -> {
			try (var region = ready(factory.open())) {
				var root = region.root();
				var inner = ready(region.child(root, 1));
				var firstProof = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root, inner }));
				var secondProof = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { inner, root }));
				try (var request = ready(factory.openStrategyRequest(region, root, context));
						var active = ready(request.activate())) {
					var first = ready(request.recognize(ready(request.bindCoverage(firstProof))));
					var second = ready(request.recognize(ready(request.bindCoverage(secondProof))));
					var one = ready(request.detach(first, "rdf4j.test", "fused", 1));
					var two = ready(request.detach(second, "rdf4j.test", "fused", 1));
					assertEquals(one, two, "the same actual occurrences and edges have one detached identity");
					assertEquals(one.hashCode(), two.hashCode());
				}
			}
		});
	}

	@Test
	void detachedDescriptorsPreserveDifferentActualCostingContexts() {
		AtomicReference<PackedStrategyRequest.Descriptor> leaf = new AtomicReference<>();
		AtomicReference<PackedStrategyRequest.Descriptor> prefixed = new AtomicReference<>();
		PackedCostModel model = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				throw new AssertionError("the actual session owns costing");
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query, PackedProviderWork work,
					PackedProviderMemory memory) {
				return new PackedCostSession() {
					private PackedPhysicalRegion.Factory factory;
					private PackedPhysicalRegion region;
					private PackedPhysicalRegion.Coverage raw;

					@Override
					public void bindPhysicalRegions(PackedPhysicalRegion.Factory value) {
						factory = value;
					}

					private PackedStrategyRequest.Descriptor capture(PackedCostContext context) {
						if (region == null) {
							region = ready(factory.open());
							var root = region.root();
							raw = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root }));
						}
						try (var request = ready(factory.openStrategyRequest(region, region.root(), context));
								var active = ready(request.activate())) {
							var candidate = ready(request.recognize(ready(request.bindCoverage(raw))));
							return ready(request.detach(candidate, "rdf4j.test", "fused", 1));
						}
					}

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						output.setRows(1, 1);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						output.setRows(1, 1);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (relationId == query.rootRelationId() && !context.hasPhysicalJoinRefinement()) {
							if (context.prefixRelationCount() == 0 && leaf.get() == null) {
								leaf.set(capture(context));
							} else if (context.prefixRelationCount() > 0 && prefixed.get() == null) {
								prefixed.set(capture(context));
							}
						}
						output.setRows(1, 1);
					}

					@Override
					public void close() {
						if (region != null) {
							region.close();
						}
					}
				};
			}
		};
		TupleExpr source = new Join(pattern("a"), new Join(pattern("b"), pattern("c")));
		PackedCascadesPlanner.optimize(source, OptimizationGoal.root(),
				new PackedPlannerLimits(1_000_000L, Long.MAX_VALUE, 64L * 1024 * 1024), model);
		assertNotNull(leaf.get());
		assertNotNull(prefixed.get(), "the provider must receive a real prefix callback");
		assertNotEquals(leaf.get(), prefixed.get(), "descriptor identity includes its actual costing context");
	}

