	@Test
	void unknownExecutionOverlapDoesNotProduceKnownPeakMemory() {
		runProvider((factory, work, memory, context) -> {
			try (var region = ready(factory.open())) {
				var root = region.root();
				var left = ready(region.child(root, 0));
				var proof = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root, left }));
				try (var request = ready(factory.openStrategyRequest(region, root, context));
						var active = ready(request.activate())) {
					var candidate = ready(request.recognize(ready(request.bindCoverage(proof))));
					var peak = new PhysicalQuantity(PackedStrategyRequest.Dimension.PEAK_MEMORY_BYTES, 10, 10, 10,
							PackedStrategyRequest.Lineage.EXACT);
					var quote = ready(
							request.quote(candidate, new PackedStrategyRequest.Quantity[] { peak, new Quantity(9) }));
					var child = ready(request.boundary(candidate, 0, PackedStrategyRequest.BoundaryScope.INCLUSIVE,
							new PackedStrategyRequest.Quantity[] { peak, new Quantity(20) }));
					var result = request.compose(candidate, quote, new PackedStrategyRequest.Boundary[] { child });
					var composed = ready(result);
					assertFalse(composed.isKnown(PackedStrategyRequest.Dimension.PEAK_MEMORY_BYTES),
							"without an execution-lifetime proof, max(child, covered) is not a proved peak");
					assertEquals(29, composed.point(PackedStrategyRequest.Dimension.SOURCE_ROW_EVENTS));
				}
			}
		});
	}

	@Test
	void nestedVectorReuseRequiresAProvedInputContext() {
		runProvider((factory, work, memory, context) -> {
			try (var region = ready(factory.open())) {
				var root = region.root();
				var inner = ready(region.child(root, 1));
				var outerProof = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root }));
				var innerProof = ready(region.cover(inner, new PackedPhysicalRegion.Occurrence[] { inner }));
				try (var request = ready(factory.openStrategyRequest(region, root, context));
						var active = ready(request.activate())) {
					var outer = ready(request.recognize(ready(request.bindCoverage(outerProof))));
					assertThrows(IllegalArgumentException.class, () -> request.recognizeNested(outer, 0, innerProof));
					assertEquals(PackedPhysicalRegion.Status.EVIDENCE_UNAVAILABLE,
							request.recognizeNested(outer, 1, innerProof).status());
					var nested = ready(request.boundary(outer, 1, PackedStrategyRequest.BoundaryScope.INCLUSIVE,
							quantities(20)));
					var result = ready(request.compose(outer, ready(request.quote(outer, quantities(2))),
							new PackedStrategyRequest.Boundary[] {
									ready(request.boundary(outer, 0, PackedStrategyRequest.BoundaryScope.LOCAL,
											quantities(7))),
									nested }));
					assertEquals(29.0d, result.point(PackedStrategyRequest.Dimension.SOURCE_ROW_EVENTS));
				}
			}
		});
	}

